CREATE TABLE staff_roles(user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL,PRIMARY KEY(user_id,role));
CREATE TABLE service_entries(id TEXT PRIMARY KEY,kind TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),data TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX service_owner ON service_entries(owner_id,kind);
CREATE TABLE case_assignments(case_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(case_id,user_id));
CREATE TABLE audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE entry_events(id INTEGER PRIMARY KEY AUTOINCREMENT,entry_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_requests(id TEXT PRIMARY KEY,entry_id TEXT,amount_paisa INTEGER NOT NULL CHECK(amount_paisa>0),currency TEXT NOT NULL DEFAULT 'PKR' CHECK(currency='PKR'),fund TEXT NOT NULL CHECK(fund IN ('zakat','general')),purpose TEXT NOT NULL,creator_id TEXT NOT NULL REFERENCES users(id),threshold_paisa INTEGER NOT NULL CHECK(threshold_paisa>0),state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','paid','cancelled')),bank_reference TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_approvals(payment_id TEXT NOT NULL REFERENCES payment_requests(id),approver_id TEXT NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(payment_id,approver_id));
CREATE TRIGGER approval_distinct_from_creator BEFORE INSERT ON payment_approvals WHEN (SELECT creator_id FROM payment_requests WHERE id=NEW.payment_id)=NEW.approver_id BEGIN SELECT RAISE(ABORT,'Creator cannot approve own payment'); END;
CREATE TRIGGER paid_requires_approvals BEFORE UPDATE OF state ON payment_requests WHEN NEW.state='paid' AND ((SELECT COUNT(*) FROM payment_approvals WHERE payment_id=NEW.id)<CASE WHEN NEW.amount_paisa>NEW.threshold_paisa THEN 2 ELSE 1 END OR NEW.bank_reference IS NULL OR LENGTH(TRIM(NEW.bank_reference))=0) BEGIN SELECT RAISE(ABORT,'Payment requires independent approvals and bank reference'); END;
CREATE TRIGGER payment_immutable BEFORE UPDATE OF amount_paisa,fund,threshold_paisa,currency,creator_id ON payment_requests BEGIN SELECT RAISE(ABORT,'Payment terms cannot be changed'); END;
CREATE TABLE donation_allocations(id TEXT PRIMARY KEY,donation_id TEXT NOT NULL REFERENCES records(id),case_id TEXT NOT NULL REFERENCES service_entries(id),payment_id TEXT REFERENCES payment_requests(id),amount_paisa INTEGER NOT NULL CHECK(amount_paisa>0),currency TEXT NOT NULL,label TEXT NOT NULL,delivery_status TEXT NOT NULL DEFAULT 'allocated',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER allocation_budget BEFORE INSERT ON donation_allocations WHEN (SELECT status FROM records WHERE id=NEW.donation_id)!='confirmed' OR NEW.currency!=json_extract((SELECT data FROM records WHERE id=NEW.donation_id),'$.currency') OR NEW.amount_paisa+COALESCE((SELECT SUM(amount_paisa) FROM donation_allocations WHERE donation_id=NEW.donation_id),0)>CAST(ROUND(json_extract((SELECT data FROM records WHERE id=NEW.donation_id),'$.amount')*100) AS INTEGER) BEGIN SELECT RAISE(ABORT,'Allocation exceeds confirmed donation or currency differs'); END;
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings VALUES('payment_threshold','50000'),('tax_exempt','false'),('tax_registration','');
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,link TEXT NOT NULL,read_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subscriptions(user_id TEXT PRIMARY KEY REFERENCES users(id),unit_id TEXT,wing TEXT CHECK(wing IN ('brothers','sisters')),city TEXT,blood_group TEXT,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE participation(entry_id TEXT NOT NULL REFERENCES service_entries(id),user_id TEXT NOT NULL REFERENCES users(id),response TEXT NOT NULL,PRIMARY KEY(entry_id,user_id));
CREATE TABLE private_files(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES service_entries(id),storage_key TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,uploaded_by TEXT NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE legacy_report_meta(record_id TEXT PRIMARY KEY REFERENCES records(id),authority_reference TEXT NOT NULL DEFAULT '',authority TEXT NOT NULL DEFAULT '',updated_by TEXT REFERENCES users(id));
CREATE TABLE credentials(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),entry_id TEXT REFERENCES service_entries(id),course_id TEXT REFERENCES resources(id),kind TEXT NOT NULL,display_name TEXT NOT NULL,details TEXT NOT NULL,expires TEXT,revoked INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER allocations_match_fund BEFORE INSERT ON donation_allocations WHEN (json_extract((SELECT data FROM records WHERE id=NEW.donation_id),'$.fund')='zakat' AND NEW.payment_id IS NOT NULL AND (SELECT fund FROM payment_requests WHERE id=NEW.payment_id)!='zakat') BEGIN SELECT RAISE(ABORT,'Zakat must remain in zakat fund'); END;
CREATE UNIQUE INDEX help_duplicate_active ON service_entries(json_extract(data,'$.cnic'),json_extract(data,'$.category')) WHERE kind='help' AND status NOT IN ('received','declined');
CREATE TABLE confidential_support(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL,data TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',reply TEXT NOT NULL DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER repayment_limit BEFORE UPDATE OF status ON service_entries WHEN NEW.kind='repayment' AND NEW.status='confirmed' AND OLD.status!='confirmed' AND COALESCE((SELECT SUM(json_extract(data,'$.amount')) FROM service_entries WHERE kind='repayment' AND status='confirmed' AND json_extract(data,'$.loanId')=json_extract(NEW.data,'$.loanId') AND id!=NEW.id),0)+json_extract(NEW.data,'$.amount')>COALESCE((SELECT json_extract(data,'$.amount') FROM service_entries WHERE id=json_extract(NEW.data,'$.loanId') AND kind='loan'),0) BEGIN SELECT RAISE(ABORT,'Repayments exceed loan principal'); END;
